def topo_sort(edges: list[tuple[str, str]]) -> list[str]:
    """
    Returns a valid topological order for a directed acyclic graph.
    Raises ValueError if the graph contains a cycle.
    """
    # Build adjacency list
    graph = {node: [] for node in edges[0]}
    for u, v in edges:
        graph[u].append(v)

    # Check for cycles using DFS
    visited = set()
    stack = []

    def dfs(node):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                stack.append(neighbor)
            else:
                # Found a cycle, return the path
                return [node] + stack

    for node in graph:
        if node not in visited:
            stack.append(node)
            while stack:
                current = stack.pop()
                if current in visited:
                    raise ValueError(f"Cycle detected in graph: {current}")
                dfs(current)

    return list(visited)
